from pathlib import Path
import json,sqlite3,hashlib,sys,datetime
P=Path(__file__).resolve().parent;L=P.parents[3];sys.path.insert(0,str(L))
from ingest import source_notes
from run_exhaustive import validate_answer
sha=lambda x:hashlib.sha256(x if isinstance(x,bytes)else(x or'').encode()).hexdigest()
scopes=json.loads((L/'runtime/export-source/securite-sociale.json').read_text());e=next(x for x in scopes if x['number']=='L133-11');key=e['code_id'],e['source_id'];db=sqlite3.connect('file:'+str(L/'corpus.sqlite')+'?mode=ro',uri=True);db.row_factory=sqlite3.Row;db.execute('BEGIN');s=dict(db.execute('SELECT * FROM articles WHERE code_id=? AND id=?',key).fetchone());s['source_id']=s.pop('id');s['source_xml']=s.pop('content_xml');s['source_notes_xml']=source_notes(db,*key);s['source_body_sha256']=sha(s['source_xml']);s['source_notes_sha256']=sha(s['source_notes_xml']);d=dict(db.execute('SELECT * FROM drafts WHERE code_id=? AND source_id=?',key).fetchone());d['proposed_sha256']=sha(d['proposed_xml']);s.update(previous_draft=d,current_beforeimage_sha256=d['proposed_sha256'],benefit_check_required=True,impact_check_required=True,source_url='https://www.legifrance.gouv.fr/codes/article_lc/'+key[1],slug='securite-sociale');raw=db.execute("SELECT xml,sha256 FROM documents WHERE code_id=? AND id=? AND kind='ARTICLE'",key).fetchone();doc=raw[0].decode()if isinstance(raw[0],bytes)else raw[0];assert sha(doc)==s['source_sha256']==raw[1];s.update(source_document_xml=doc,source_document_sha256=sha(doc));db.rollback();db.close();(P/'source.json').write_text(json.dumps([s],ensure_ascii=False,indent=2)+'\n')
old="Le tiers déclarant informe son client de la décision de retrait dans un délai fixé par décret en Conseil d'État."
new="L’information donnée sans délai au cotisant par cet organisme tient lieu d’information du client sur la décision de retrait. Le tiers déclarant n’est pas tenu d’en adresser une seconde notification à son client. Les modalités réglementaires d’application ne peuvent rétablir cette seconde notification ; elles maintiennent la notification par l’organisme, les droits de défense et de recours, ainsi que la restitution au client des pièces lui appartenant."
body=d['proposed_xml'];assert body.count(old)==1;body=body.replace(old,new)
transition="<p>La suppression de la seconde notification par le tiers déclarant s’applique aux décisions de retrait notifiées à compter de l’entrée en vigueur de la loi qui l’institue. Elle ne retire ni l’obligation pour l’organisme d’informer sans délai le cotisant, ni les voies de recours, ni les créances, droits et obligations de restitution des pièces ; elle ne remet pas en cause les décisions de retrait antérieures ni les règles qui leur étaient applicables.</p>";body+=transition
row={k:s[k]for k in ['code_id','source_id','source_sha256','number']};row.update(status='rewrite_draft',proposed_xml=body,reason='Supprime au niveau législatif l’obligation de seconde notification du retrait par le tiers déclarant, déjà couverte par l’information sans délai du cotisant par l’organisme. Coordination indispensable à la coupe de R133-44 ; toutes les autres conditions et garanties du mandat demeurent.',review_notes='Source officielle, notes et proposition courante lues en entier. Seule la dernière phrase du quatrième alinéa du I est remplacée ; une transition est ajoutée après IV. Les quatre divisions et leurs autres dispositions sont inchangées par rapport à l’avant-image. Le législateur supprime lui-même l’obligation que le décret ne pouvait retirer seul : le R133-44 proposé ne doit pas être présenté comme une suppression effective sans cette coordination. Conserver l’information sans délai par l’organisme, fraude et complicité, retrait personnel, plafond de cinq ans, contradictoire, recours et restitution du règlement. Les notes de 2018 concernent les démarches des indépendants, sans nouveau départ de délai. Relecture indépendante et gardes sous verrou requises avant inscription.',benefit_review='Le choix libre du mandataire et la possibilité de déléguer la déclaration demeurent ; l’employeur ou indépendant conserve tous ses droits et obligations. Le client reste informé sans délai par l’organisme, retrouve ses pièces dans les conditions réglementaires et conserve ses recours. Seule la seconde notification par le tiers est supprimée pour les décisions futures. Aucun avantage social, remise, exonération, droit de rectification ou situation future éligible n’est fermé ; aucune nouvelle cotisation ou formalité de remplacement n’est créée.',substantive_impact=dict(version=1,classification='material_reduction',assessment='La source législative impose deux informations, celle de l’organisme sans délai et celle du tiers dans un délai réglementaire. Supprimer seulement la seconde dans R133-44 était insuffisant. Le présent article retire son obligation législative et empêche son rétablissement réglementaire ; l’information de l’organisme reste due. Il s’agit de la même mesure, dédupliquée, et non d’un cinquième allègement autonome.',scope_limitations='Effet prospectif des textes proposés, sous réserve de leur adoption et coordination des dates d’application ; aucun texte de ce paquet n’est encore inscrit ou en vigueur. Pas de remise générale des décisions anciennes ni de chiffrage national. Fraude, secret, recouvrement, sanctions autonomes et protection des clients restent dans leur champ.',new_burdens_review='Aucune nouvelle lettre ni attestation n’est exigée. La notification de l’organisme, la restitution et les recours existaient dans le circuit source ; leur maintien ne crée pas de charge de remplacement. Les autres formalités et la voie dématérialisée restent inchangées, sans nouveau taux ni obligation d’inscription.',effects=[dict(kind='obligation_removed',measure_id='mandataire-double-avis-retrait',description='Suppression législative du second avis de retrait par le mandataire.',before='L’organisme informe sans délai le cotisant ; le tiers doit informer encore son client dans le délai du décret, fixé à huit jours dans R133-44.',after='L’information sans délai de l’organisme suffit ; aucun second avis du tiers ne peut être exigé sur ce fondement, restitution et recours maintenus.',unit='legal_duty',affected_population='Tiers déclarants, employeurs et travailleurs indépendants qui leur confient des formalités sociales.',conditions_and_transition='Décisions de retrait notifiées après entrée en vigueur de la loi proposée ; dispositions anciennes et décisions antérieures non annulées. Coordination conjointe avec R133-44 avant de présenter la suppression comme opérante.',replacement_or_new_burdens='Aucune nouvelle notification ou inscription ; notification de l’organisme et garanties réglementaires déjà existantes conservées.',source_quote="Le tiers déclarant informe son client de la décision de retrait dans un délai défini par décret en Conseil d'Etat.",proposed_quote='Le tiers déclarant n’est pas tenu d’en adresser une seconde notification à son client.')]))
validate_answer([row],[s]);(P/'answer.json').write_text(json.dumps([row],ensure_ascii=False,indent=2)+'\n')
policies={}
for name in ['policy-coordinations.json','site-summaries.json']:
 raw=(L/name).read_bytes();(P/name).write_bytes(raw);policies[name]=sha(raw)
peer=json.loads((L/'runtime/poursuite-20261020/social/edition001/source.json').read_text());peer_rows=json.loads((L/'runtime/poursuite-20261020/social/edition001/answer.json').read_text());r=next(x for x in peer_rows if x['number']=='R133-44');src=next(x for x in peer if x['number']=='R133-44');(P/'paired-r133-44.json').write_text(json.dumps(dict(source=src,proposal=r,frozen_answer_file_sha256=sha((L/'runtime/poursuite-20261020/social/edition001/answer.json').read_bytes())),ensure_ascii=False,indent=2)+'\n')
