db=sqlite3.connect('file:'+str(L/'corpus.sqlite')+'?mode=ro',uri=True);db.execute('BEGIN');assert db.execute('SELECT source_sha256,content_xml FROM articles WHERE code_id=? AND id=?',key).fetchone()==(s['source_sha256'],s['source_xml']);assert source_notes(db,*key)==s['source_notes_xml'];assert db.execute('SELECT source_sha256,proposed_xml FROM drafts WHERE code_id=? AND source_id=?',key).fetchone()==(d['source_sha256'],d['proposed_xml']);db.rollback();db.close();assert all(sha((L/n).read_bytes())==h for n,h in policies.items())
report=dict(checked_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_and_notes_and_beforeimage_match=True,previous_draft_sha256=d['proposed_sha256'],schema_valid=True,policy_sha256=policies,source_file_sha256=sha((P/'source.json').read_bytes()),answer_file_sha256=sha((P/'answer.json').read_bytes()),source_document_sha256=s['source_sha256'],paired_measure_id='mandataire-double-avis-retrait',additional_independent_cuts=0,legislative_coordination_required_before_regulatory_cut_effective=True,database_modified=False,registered=False,published=False)
(P/'validation.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report,ensure_ascii=False,indent=2))
